using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ShootingStarOmenData", menuName = "Data/Battle/Omens System/Omen Data/Orion/ShootingStar Omen Data")]
public class ShootingStarOmenData : OmenData
{
	[Header("Moving Star Omen")]
	[SerializeField]
	private CosmicOrbStarAbility cosmicOrbStarAbility;

	[SerializeField]
	private OmenLogic randomTargetOmenLogic;

	public OmenLogic RandomTargetOmenLogic => randomTargetOmenLogic;

	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<OrionOmensHandler>.Instance.ShootingStarOmenAction = delegate
		{
			cosmicOrbStarAbility.OnActivateStarAbility();
		};
		ReferenceSingleton<OrionOmensHandler>.Instance.ShootingStarOmenFeedbackAction = delegate
		{
			omenInstance.EnqueueOmenFeedbackAndPlay();
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<OrionOmensHandler>.Instance.ShootingStarOmenAction = null;
		ReferenceSingleton<OrionOmensHandler>.Instance.ShootingStarOmenFeedbackAction = null;
	}

	public override string OmenConvertedDescription()
	{
		string arg = Smart.Format(base.localizationManager.GetLocalizedCastOrbActionBase(), cosmicOrbStarAbility.GetLocalizedNameWithoutModifiers());
		return Smart.Format(base.OmenConvertedDescription(), arg);
	}
}
